// ── JALAPAO — dunes + fervedouros + buriti palms ──
// Runtime vars: svg, w, h, bY, bCol, wc, ol, isN, mt, w1, w2, w3, sc

// Sky
svg += `<defs><linearGradient id="lg-jalapao" x1="0" y1="0" x2="0" y2="1">
  <stop offset="0%" stop-color="${isN ? '#10213E' : sc.sky1}"/>
  <stop offset="100%" stop-color="${isN ? '#1F365D' : sc.sky2}"/>
</linearGradient></defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-jalapao)"/>`;

// Sun / moon
if (!isN) {
  svg += `<circle cx="${w * 0.78}" cy="${h * 0.16}" r="${36 + w1 * 8}" fill="#FFD27A" opacity="0.75"/>`;
  svg += `<circle cx="${w * 0.78}" cy="${h * 0.16}" r="${62 + w1 * 12}" fill="#FFD27A" opacity="0.14"/>`;
} else {
  svg += `<circle cx="${w * 0.78}" cy="${h * 0.16}" r="18" fill="#EFE7D3" opacity="0.9"/>`;
}

const duneBaseY = bY - 6;

// Dune layers
for (let layer = 0; layer < 3; layer++) {
  const amp = 18 - layer * 4;
  const speed = 0.18 + layer * 0.07;
  const y = duneBaseY + layer * 18;
  const c = layer === 0 ? '#D99E43' : layer === 1 ? sc.acc : '#A87935';
  let d = `M0 ${y}`;
  for (let x = 0; x <= 8; x++) {
    const px = (w / 8) * x;
    const py = y + Math.sin(mt * speed + x * 0.9 + layer) * amp;
    d += ` L${px} ${py}`;
  }
  d += ` L${w} ${h} L0 ${h} Z`;
  svg += `<path d="${d}" fill="${c}" opacity="${0.65 - layer * 0.12}"/>`;
}

// Emerald river ribbon
const riverY = h * 0.68;
let river = `M0 ${riverY}`;
for (let x = 0; x <= 10; x++) {
  const px = (w / 10) * x;
  const py = riverY + Math.sin(mt * 0.45 + x * 1.15) * 10;
  river += ` L${px} ${py}`;
}
river += ` L${w} ${h} L0 ${h} Z`;
svg += `<path d="${river}" fill="${isN ? '#123550' : '#2CA9BC'}" opacity="0.78"/>`;

// Water ripples
for (let i = 0; i < 6; i++) {
  const ry = riverY + 8 + i * 8 + Math.sin(mt * 1.6 + i) * 1.8;
  svg += `<path d="M0 ${ry} Q ${w * 0.3} ${ry + 3 * w2} ${w * 0.6} ${ry} T ${w} ${ry}" fill="none" stroke="${isN ? '#67B8D5' : '#DFFFFF'}" stroke-opacity="0.28" stroke-width="1.5"/>`;
}

// Fervedouro (bubbling spring)
const fx = w * 0.28;
const fy = h * 0.73;
svg += `<ellipse cx="${fx}" cy="${fy}" rx="55" ry="18" fill="${isN ? '#1E6F85' : '#49D0D8'}" opacity="0.72"/>`;
for (let i = 0; i < 9; i++) {
  const bx = fx - 40 + i * 10 + Math.sin(mt * 1.9 + i) * 3;
  const by = fy - Math.abs(Math.sin(mt * 2.3 + i * 1.2)) * 16;
  const br = 1.8 + (Math.sin(mt * 2.1 + i) * 0.5 + 0.5) * 2.4;
  svg += `<circle cx="${bx}" cy="${by}" r="${br}" fill="#ECFFFF" opacity="0.7"/>`;
}

// Buriti palms
for (let i = 0; i < 4; i++) {
  const tx = w * 0.58 + i * 52;
  const sway = Math.sin(mt * 0.9 + i * 0.7) * 4;
  svg += `<path d="M${tx} ${duneBaseY - 8} Q ${tx + sway} ${duneBaseY - 50} ${tx + sway * 1.2} ${duneBaseY - 105}" stroke="#7A5A32" stroke-width="6" fill="none" stroke-linecap="round"/>`;
  for (let k = 0; k < 6; k++) {
    const ang = -1.25 + k * 0.5 + Math.sin(mt + i + k) * 0.04;
    const lx = tx + sway * 1.2 + Math.cos(ang) * 34;
    const ly = duneBaseY - 105 + Math.sin(ang) * 20;
    svg += `<line x1="${tx + sway * 1.2}" y1="${duneBaseY - 105}" x2="${lx}" y2="${ly}" stroke="#2E7D52" stroke-width="3" stroke-linecap="round"/>`;
  }
}

// Plateau silhouettes
for (let i = 0; i < 3; i++) {
  const mx = w * 0.1 + i * w * 0.22;
  const mh = 45 + i * 12 + w3 * 5;
  svg += `<path d="M${mx} ${bY} L${mx + 35} ${bY - mh} L${mx + 86} ${bY} Z" fill="${sc.bld}" opacity="0.65"/>`;
}

// Birds
for (let i = 0; i < 3; i++) {
  const bx = w * (0.2 + i * 0.14) + Math.sin(mt * 0.5 + i) * 20;
  const by = h * 0.24 + Math.sin(mt * 0.9 + i * 1.4) * 10;
  svg += `<path d="M${bx - 7} ${by} q7 -5 14 0" stroke="${isN ? '#CFD7E1' : '#2F3A43'}" stroke-width="1.4" fill="none" stroke-linecap="round"/>`;
}

// Warm legal marker stone (article/provenance metaphor)
const stoneX = w * 0.84;
const stoneY = duneBaseY - 12;
svg += `<rect x="${stoneX}" y="${stoneY}" width="32" height="24" rx="4" fill="#8E7C63" stroke="#4A3F34" stroke-width="${Math.max(1, ol * 0.5)}"/>`;
svg += `<circle cx="${stoneX + 16}" cy="${stoneY + 12}" r="${3.5 + w2 * 1.5}" fill="#FFD27A" opacity="${isN ? 0.8 : 0.35}"/>`;
